  s->sn = t->sn;
  s->sz = t->sz;
}
#endif

static void
mpz_set_int(mrb_state *mrb, mpz_t *y, mrb_int v)
{
  for (size_t i=1; i<y->sz; i++)
    y->p[i] = 0;
  if (v < 0) {
    y->sn = -1;
    y->p[0] = (-v) & LMAX;
    y->p[1] = ((-v) & LC) >> DIGITBITS;
  }
  else if (v > 0) {
    y->sn = 1;
    y->p[0] = v & LMAX;
    y->p[1] = (v & LC) >> DIGITBITS;
  }
  else {
    y->sn=0;
    y->p[0] = 0;
    y->p[1] = 0;
  }
}

static void
mpz_init_set_int(mrb_state *mrb, mpz_t *y, mrb_int v)
{
  mp_limb u;

  y->p = (mp_limb*)mrb_malloc(mrb, sizeof(mp_limb)*2);
  if (v < 0) {
    y->sn = -1;
    u = -v;
  }
  else if (v > 0) {
    y->sn = 1;
    u = v;
  }
  else {
    y->sn=0;
    u = 0;
  }
  y->p[0] = u & LMAX;
  y->p[1] = (u & LC) >> DIGITBITS;
  y -> sz = 2;
}

static void
mpz_clear(mrb_state *mrb, mpz_t *s)
{
  if (s->p)
    mrb_free(mrb, s->p);
  s->p=NULL;
  s->sn=0;
  s->sz=0;
}

static void
mpz_realloc(mrb_state *mrb, mpz_t *x, size_t size)
{
  if (size > 1 && x->sz < size) {
    x->p=(mp_limb*)mrb_realloc(mrb,x->p,size * sizeof(mp_limb));
    for (size_t i=x->sz; i<size; i++)
      (x->p)[i] = 0;
    x->sz = size;
  }
}

static size_t
digits(mpz_t *x)
{
  size_t i;
  for (i = (x->sz) - 1; (x->p)[i] == 0 ; i--)
    if (i == 0) break;
  return i+1;
}

/* y = x */
static void
mpz_set(mrb_state *mrb, mpz_t *y, mpz_t *x)
{
  size_t i,k = x->sz;
  if (y->sz < k) {
    k=digits(x);
    mpz_realloc(mrb, y, (size_t)k);
  }
  if (y->sz > x->sz) {
    mpz_clear(mrb, y);
    mpz_init(mrb, y);
    mpz_realloc(mrb, y, (size_t)(x->sz));
  }

  for (i=0;i < k; i++)
    (y->p)[i] = (x->p)[i];

  for (;i<y->sz;i++)
    (y->p)[i] = 0;

  y->sn = x->sn;
}

/* z = x + y, without regard for sign */
static void
uadd(mrb_state *mrb, mpz_t *z, mpz_t *x, mpz_t *y)
{
  mp_limb c;
  size_t i;
  mpz_t *t;

  if (y->sz < x->sz) {
    t=x; x=y; y=t;
  }

  /* now y->sz >= x->sz */

  mpz_realloc(mrb, z, (size_t)((y->sz)+1));

  c=0;
  for (i=0; i<x->sz; i++) {
    if ((z->p[i] = y->p[i] + x->p[i] + c) & CMASK) {
      c=1;
      (z->p[i]) &=LMAX;
    }
    else
      c=0;
  }
  for (;i<y->sz; i++) {
    if ((z->p[i] = (y->p[i] + c)) & CMASK)
      z->p[i]=0;
    else
      c=0;
  }
  (z->p)[y->sz]=c;
}

/* z = y - x, ignoring sign */
/* precondition: abs(y) >= abs(x) */
static void
usub(mrb_state *mrb, mpz_t *z, mpz_t *y, mpz_t *x)
{
  mp_limb b,m;
  mpz_realloc(mrb, z, (size_t)(y->sz));
  b=0;
  for (size_t i=0;i<y->sz;i++) {
    m=((y->p)[i]-b)-dg(x,i);
    if (m < 0) {
      b = 1;
      m = LMAX + 1 + m;
    }
    else
      b = 0;
    z->p[i] = m;
  }
}

/* compare abs(x) and abs(y) */
static int
ucmp(mpz_t *y, mpz_t *x)
{
  size_t i;
  for (i=imax(x->sz,y->sz)-1;;i--) {
    if (dg(y,i) < dg(x,i))
      return (-1);
    else if (dg(y,i) > dg(x,i))
      return 1;
    if (i == 0) break;
  }
  return 0;
}

static int
uzero(mpz_t *x)
{
  for (size_t i=0; i < x->sz; i++)
    if ((x->p)[i] != 0)
      return 0;
  return 1;
}

static void
zero(mpz_t *x)
{
  x->sn=0;
  for (size_t i=0;i<x->sz;i++)
    (x->p)[i] = 0;
}

/* z = x + y */
static void
mpz_add(mrb_state *mrb, mpz_t *zz, mpz_t *x, mpz_t *y)
{
  int mg;
  mpz_t z;
  if (x->sn == 0) {
    mpz_set(mrb, zz, y);
    return;
  }
  if (y->sn == 0) {
    mpz_set(mrb, zz, x);
    return;
  }
  mpz_init(mrb, &z);

  if (x->sn > 0 && y->sn > 0) {
    uadd(mrb, &z, x, y);
    z.sn = 1;
  }
  else if (x->sn < 0 && y->sn < 0) {
    uadd(mrb, &z, x, y);
    z.sn = -1;
  }
  else {
    /* signs differ */
    if ((mg = ucmp(x,y)) == 0) {
      zero(&z);
    }
    else if (mg > 0) {  /* abs(y) < abs(x) */
      usub(mrb, &z, x, y);
      z.sn = (x->sn > 0 && y->sn < 0) ? 1 : (-1);
    }
    else { /* abs(y) > abs(x) */
      usub(mrb, &z, y, x);
      z.sn = (x->sn < 0 && y->sn > 0) ? 1 : (-1);
    }
